parameters.jsCode:
const item = $input.first();
const j = (item && item.json) || {};

// 對未執行的節點呼叫 $() 會拋例外，必須逐一保護
const pick = (nodeName, key) => {
  try {
    const ref = $(nodeName).first();
    return ref && ref.json ? ref.json[key] : undefined;
  } catch (e) {
    console.log('[Normalize Error] 節點 ' + nodeName + ' 未執行，略過取值: ' + e.message);
    return undefined;
  }
};
const reached = (nodeName) => {
  try { return !!$(nodeName).first(); } catch (e) { return false; }
};

let triggerEvent = {};
try {
  const t = $('Slack Message Trigger').first();
  triggerEvent = (t && t.json && (t.json.event || t.json)) || {};
} catch (e) {
  console.log('[Normalize Error] trigger 不可讀: ' + e.message);
}

const threadTs =
  pick('Parse AI Response', 'threadTs') ||
  pick('Collect Thread Context', 'threadTs') ||
  j.threadTs || j.thread_ts || j.ts ||
  triggerEvent.thread_ts || triggerEvent.ts || null;

const channel =
  pick('Parse AI Response', 'channel') ||
  pick('Collect Thread Context', 'channel') ||
  j.channel || triggerEvent.channel || 'C08NVUQUK8F';

// 失敗階段改由 $prevNode.name 判定 —— 那是 n8n 的節點層 metadata，
// 不像 $('節點名') 需要解析 item 配對，因此在錯誤分支上仍然可靠。
//
// 為什麼換掉原本的 reached()：實測 exec #1637 失敗於 Call Azure OpenAI，
// Build Azure Payload 明明執行過，reached('Build Azure Payload') 仍回 false，
// 於是 stage 落在預設值「讀取 Slack 對話」，把 AI 失敗說成 Slack 失敗。
// （注意：同一次執行中 $('Slack Message Trigger') 是成功的，所以問題不是
//  「錯誤分支不能用 $()」，而是特定節點的 item 配對解析不到。）
const STAGE_BY_NODE = {
  'Fetch Thread Replies': '讀取 Slack 對話',
  'Collect Thread Context': '整理對話內容',
  'Should Process': '整理對話內容',
  'Has Images': '整理對話內容',
  'Split Images': '處理圖片附件',
  'Download Image': '下載 Slack 圖片',
  'Aggregate Images': '處理圖片附件',
  'Build Azure Payload': '組裝 AI 請求',
  'Analyze With Azure': '呼叫 AI 解析',
  'Parse AI Response': '解析 AI 回應',
  'Route Outcome': '判斷處理方式',
  'Create Calendar Event': '建立 Google 日曆事件',
  'Update Calendar Event': '更新 Google 日曆事件',
  'Send Success Card': '傳送 Slack 通知卡片',
  'Send Updated Card': '傳送 Slack 通知卡片',
  'Send Clarify Card': '傳送 Slack 通知卡片',
  'Send Duplicate Notice': '傳送 Slack 通知卡片',
  'Send Not Owner Card': '傳送 Slack 通知卡片',
  'Verify Card Delivery': '傳送 Slack 通知卡片',
  'Verify Updated Card Delivery': '傳送 Slack 通知卡片',
  'Verify Notice Delivery': '傳送 Slack 通知卡片',
};
let failedNode = null;
try {
  if (typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name) failedNode = $prevNode.name;
} catch (e) {
  console.log('[Normalize Error] $prevNode 不可讀: ' + e.message);
}
let stage = failedNode && STAGE_BY_NODE[failedNode] ? STAGE_BY_NODE[failedNode] : null;
if (!stage) {
  // 舊的節點回推法留作退路，若 $prevNode 也取不到才會用到
  stage = '讀取 Slack 對話';
  if (reached('Parse AI Response')) stage = '建立／更新 Google 日曆事件';
  else if (reached('Build Azure Payload')) stage = '呼叫 AI 解析';
  else if (reached('Collect Thread Context')) stage = '整理對話內容';
  console.log('[Normalize Error] $prevNode 無法對應階段，退回節點回推法。failedNode=' + JSON.stringify(failedNode));
}

// 日曆是否已經寫入成功，決定了要給使用者哪一種指示。
// 若日曆已建立、只是通知卡片沒送出去，卻叫使用者「重試或手動建立」，
// 使用者照做就會得到兩個重複的事件 —— 錯誤訊息本身造成了它宣稱要避免的問題
// （rd-json BLOCKING #4）。因此這裡明確回讀日曆節點是否留下 event id。
const calendarEventId =
  pick('Create Calendar Event', 'id') ||
  pick('Update Calendar Event', 'id') || null;
const calendarLink =
  pick('Create Calendar Event', 'htmlLink') ||
  pick('Update Calendar Event', 'htmlLink') || null;
// 日曆是否已寫入，不能只靠 pick() —— 它和 reached() 是同一套 $() 機制，
// 在錯誤分支上可能取不到值。誤判為 false 的代價很具體：錯誤卡會叫使用者
// 「重試或手動建立」，使用者照做就會得到兩個重複事件（rd-json BLOCKING #4）。
// 因此改以「失敗發生在哪一個節點」為主要判準：只要已經走到卡片傳送階段，
// 日曆必然已經寫入成功，因為卡片節點在日曆節點之後。
const FAILED_AFTER_CALENDAR = new Set([
  'Send Success Card', 'Send Updated Card',
  'Verify Card Delivery', 'Verify Updated Card Delivery',
]);
const calendarWritten = !!calendarEventId || (!!failedNode && FAILED_AFTER_CALENDAR.has(failedNode));
if (calendarWritten) stage = '傳送 Slack 通知卡片';
if (calendarWritten && !calendarEventId) {
  console.log('[Normalize Error] 依失敗節點判定日曆已寫入，但取不到 event id。failedNode=' + failedNode);
}

// 錯誤物件的形狀依來源而異，逐一嘗試而非假設單一結構：
//   HTTP 節點逾時      -> { error: 'connect ETIMEDOUT 1.2.3.4:443' }（error 是字串）
//   Slack API 失敗     -> { error: 'channel_not_found' }（error 是錯誤碼字串）
//   n8n 包裝的節點錯誤 -> { error: { message, description, httpCode } }
//   Google API 失敗    -> { message: '...' } 或 { error: { message } }
// 舊寫法先做 j.error || {}，字串型的 error 會被當成物件去讀 .message 而得到
// undefined，最後一路落到 'unknown error' —— 對排查最有用的那一種反而被丟掉。
const err = j.error;
const candidates = [
  typeof err === 'string' ? err : null,
  err && typeof err === 'object' ? err.message : null,
  j.message,
  err && typeof err === 'object' ? err.description : null,
  j.description,
  typeof j === 'string' ? j : null,
];
const rawMessage = candidates.find((c) => typeof c === 'string' && c.trim()) || 'unknown error';

// 逾時／連線中斷有一個特別惡劣的性質：請求可能已經抵達 Google 並成功建立事件，
// 只是回應沒回來。此時我們拿不到 event id，calendarWritten 是 false，
// 但事件其實**可能已經存在**。若照一般錯誤那樣叫使用者「稍後重試或手動建立」，
// 他照做就會得到兩筆重複事件 —— 錯誤訊息本身製造了它想避免的問題。
// 所以這種情況必須改口為「先去確認」，而不是「再試一次」。
// 僅在失敗確實發生在日曆那一步時成立；更早的階段根本還沒碰到 Google。
const TIMEOUT_LIKE = /ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|ECONNABORTED|EAI_AGAIN|EPIPE|socket hang up|timed? ?out|network|Bad Gateway|Service Unavailable|Gateway Time|\b50[234]\b/i;
const uncertainWrite = !calendarWritten
  && stage === '建立／更新 Google 日曆事件'
  && TIMEOUT_LIKE.test(String(rawMessage));

return [{
  json: {
    channel,
    threadTs,
    stage,
    errorMessage: String(rawMessage).slice(0, 400),
    hasThreadTs: !!threadTs,
    calendarWritten,
    calendarEventId,
    calendarLink,
    uncertainWrite,
  },
}];

// 用白名單判定：只有明確的 ok===true 才算送達。
// 原因：卡片節點設 onError:'continueRegularOutput'，遇 5xx／連線層硬失敗時
// n8n 的 HttpRequestV3 會把 { error: msg } 推到 regular 輸出而非 error 輸出，
// 此時 ok 是 undefined。若寫成 ok === false 就會靜默放行，
// 而這張卡片的 metadata 是下一輪讀回 event ID 的唯一途徑 —— 漏掉就會重複建立事件。
//
// 逐項檢查：一則訊息可能建立多個事件、送出多張卡片。原本只看 $json（第一張），
// 後面幾張就算沒送出去也會被當成成功。
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = (items[i] && items[i].json) || {};
  if (j.ok !== true) {
    console.log('[E_SLACK_POST] 第 ' + (i + 1) + '/' + items.length + ' 張卡片投遞未確認成功: ' + JSON.stringify({
      ok: j.ok === undefined ? '(undefined)' : j.ok,
      error: j.error || null,
      warning: j.warning || null,
      response_metadata: j.response_metadata || null,
    }));
    throw new Error('[E_SLACK_POST] chat.postMessage 未回報成功（第 ' + (i + 1) + '/' + items.length + ' 張）: ' + (j.error || 'ok!==true'));
  }
  out.push({ json: { ok: true, ts: j.ts || null, channel: j.channel || null } });
}
return out;

// 用白名單判定：只有明確的 ok===true 才算送達。
// 原因：卡片節點設 onError:'continueRegularOutput'，遇 5xx／連線層硬失敗時
// n8n 的 HttpRequestV3 會把 { error: msg } 推到 regular 輸出而非 error 輸出，
// 此時 ok 是 undefined。若寫成 ok === false 就會靜默放行，
// 而這張卡片的 metadata 是下一輪讀回 event ID 的唯一途徑 —— 漏掉就會重複建立事件。
//
// 逐項檢查：一則訊息可能建立多個事件、送出多張卡片。原本只看 $json（第一張），
// 後面幾張就算沒送出去也會被當成成功。
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = (items[i] && items[i].json) || {};
  if (j.ok !== true) {
    console.log('[E_SLACK_POST] 第 ' + (i + 1) + '/' + items.length + ' 張卡片投遞未確認成功: ' + JSON.stringify({
      ok: j.ok === undefined ? '(undefined)' : j.ok,
      error: j.error || null,
      warning: j.warning || null,
      response_metadata: j.response_metadata || null,
    }));
    throw new Error('[E_SLACK_POST] chat.postMessage 未回報成功（第 ' + (i + 1) + '/' + items.length + ' 張）: ' + (j.error || 'ok!==true'));
  }
  out.push({ json: { ok: true, ts: j.ts || null, channel: j.channel || null } });
}
return out;

// 用白名單判定：只有明確的 ok===true 才算送達。
// 原因：卡片節點設 onError:'continueRegularOutput'，遇 5xx／連線層硬失敗時
// n8n 的 HttpRequestV3 會把 { error: msg } 推到 regular 輸出而非 error 輸出，
// 此時 ok 是 undefined。若寫成 ok === false 就會靜默放行，
// 而這張卡片的 metadata 是下一輪讀回 event ID 的唯一途徑 —— 漏掉就會重複建立事件。
//
// 逐項檢查：一則訊息可能建立多個事件、送出多張卡片。原本只看 $json（第一張），
// 後面幾張就算沒送出去也會被當成成功。
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = (items[i] && items[i].json) || {};
  if (j.ok !== true) {
    console.log('[E_SLACK_POST] 第 ' + (i + 1) + '/' + items.length + ' 張卡片投遞未確認成功: ' + JSON.stringify({
      ok: j.ok === undefined ? '(undefined)' : j.ok,
      error: j.error || null,
      warning: j.warning || null,
      response_metadata: j.response_metadata || null,
    }));
    throw new Error('[E_SLACK_POST] chat.postMessage 未回報成功（第 ' + (i + 1) + '/' + items.length + ' 張）: ' + (j.error || 'ok!==true'));
  }
  out.push({ json: { ok: true, ts: j.ts || null, channel: j.channel || null } });
}
return out;

// Create Calendar Event 之後，$json 只剩 Google 回傳的事件資源；解析結果（標題、
// 時間、地點、警告…）已經不在項目上。卡片先前用 $('Parse AI Response').first()
// 把它們取回來，但 .first() 永遠回第一筆 —— 一則訊息含多場會議時，第 2、3 張卡片
// 會顯示第 1 場的內容，而卡片 metadata 正是下一輪讀回 event ID 的唯一來源：
// 錯掉之後重複判定與 update 目標都會跟著錯，導致重複建立或改到別場會議。
// 這裡改用 n8n 的 item pairing 取回「這一筆」對應的解析結果。
const created = $json || {};
let src = null;
try {
  src = $('Parse AI Response').item.json;
} catch (err) {
  // pairing 失敗時「整包退回 .first()」是錯的：那正是這個節點要消滅的行為，
  // 第 2 筆會掛上第 1 筆的標題與時間並寫進卡片 metadata，之後靜默改錯事件。
  // 改成只沿用整串共用的欄位（頻道、執行緒、日曆 —— 這些每一筆本來就相同），
  // 事件本身的標題／時間／地點一律取 Google 實際建立的內容。
  // 寧可少顯示幾個輔助欄位，也不要顯示錯的事件。
  console.log('[Pair Created Event] item pairing 取不到對應項目，改用 Google 回傳內容重建：'
    + (err && err.message ? err.message : String(err)));
  let shared = {};
  try {
    shared = $('Parse AI Response').first().json || {};
  } catch (err2) {
    console.log('[Pair Created Event] 連 first() 都取不到，只能靠 Google 回傳內容：'
      + (err2 && err2.message ? err2.message : String(err2)));
  }
  const gStart = created.start || {};
  src = {
    channel: shared.channel,
    threadTs: shared.threadTs,
    calendarId: shared.calendarId,
    title: created.summary || null,
    startDateTime: gStart.dateTime || gStart.date || null,
    displayTime: gStart.dateTime || gStart.date || null,
    location: created.location || '',
    description: created.description || '',
    reasoning: '',
    imageTranscript: '',
    yearStatus: 'PASS',
    attachmentNotice: '',
    calendarWarning: '',
    eventIndex: 0,
    eventTotal: 1,
    eventsDropped: 0,
    pairingFallback: true,
  };
}
return { json: Object.assign({}, src, {
  googleEventId: created.id || null,
  googleHtmlLink: created.htmlLink || null,
}) };
